const std = @import("std");

pub const Tensor = struct {
    allocator: std.mem.Allocator,
    shape: []usize,
    data: []f32,

    pub fn init(allocator: std.mem.Allocator, shape: []const usize) !Tensor {
        if (shape.len == 0) return error.InvalidShape;
        var total: usize = 1;
        for (shape) |s| {
            if (s == 0) return error.InvalidShape;
            total = try std.math.mul(usize, total, s);
        }
        const shape_copy = try allocator.dupe(usize, shape);
        errdefer allocator.free(shape_copy);
        const data = try allocator.alloc(f32, total);
        errdefer allocator.free(data);
        @memset(data, 0);
        return Tensor{
            .allocator = allocator,
            .shape = shape_copy,
            .data = data,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
        self.* = undefined;
    }
};

pub const OFTB = struct {
    pub const FRACTAL_SCALE: f32 = 0.7071067811865476;

    dim: usize,

    pub fn init(d: usize) OFTB {
        std.debug.assert(d != 0);
        std.debug.assert(d <= std.math.maxInt(usize) / 2);
        return OFTB{
            .dim = d,
        };
    }

    pub fn deinit(self: *OFTB) void {
        self.* = undefined;
    }

    pub fn forwardInPlace(self: OFTB, x: *Tensor) !void {
        if (self.dim == 0) return error.InvalidDimension;
        if (self.dim > std.math.maxInt(usize) / 2) return error.DimensionOverflow;
        const total = self.dim * 2;
        if (x.data.len != total) return error.DimensionMismatch;
        const half = self.dim;
        const x1 = x.data[0..half];
        const x2 = x.data[half..][0..half];
        const scale: f32 = FRACTAL_SCALE;
        const VLEN: usize = 8;
        var i: usize = 0;
        while (i + VLEN <= half) : (i += VLEN) {
            const va: @Vector(VLEN, f32) = x1[i..][0..VLEN].*;
            const vb: @Vector(VLEN, f32) = x2[i..][0..VLEN].*;
            const vscale: @Vector(VLEN, f32) = @splat(scale);
            x1[i..][0..VLEN].* = (va - vb) * vscale;
            x2[i..][0..VLEN].* = (va + vb) * vscale;
        }
        while (i < half) : (i += 1) {
            const a = x1[i];
            const b = x2[i];
            x1[i] = (a - b) * scale;
            x2[i] = (a + b) * scale;
        }
    }

    pub fn backwardInPlace(self: OFTB, grad: []f32) !void {
        if (self.dim == 0) return error.InvalidDimension;
        if (self.dim > std.math.maxInt(usize) / 2) return error.DimensionOverflow;
        const total = self.dim * 2;
        if (grad.len != total) return error.DimensionMismatch;
        const half = self.dim;
        const g1 = grad[0..half];
        const g2 = grad[half..][0..half];
        const scale: f32 = FRACTAL_SCALE;
        const VLEN: usize = 8;
        var i: usize = 0;
        while (i + VLEN <= half) : (i += VLEN) {
            const va: @Vector(VLEN, f32) = g1[i..][0..VLEN].*;
            const vb: @Vector(VLEN, f32) = g2[i..][0..VLEN].*;
            const vscale: @Vector(VLEN, f32) = @splat(scale);
            g1[i..][0..VLEN].* = (va + vb) * vscale;
            g2[i..][0..VLEN].* = (vb - va) * vscale;
        }
        while (i < half) : (i += 1) {
            const a = g1[i];
            const b = g2[i];
            g1[i] = (a + b) * scale;
            g2[i] = (b - a) * scale;
        }
    }
};

pub fn mixForward(oftb: OFTB, x: *Tensor) !void {
    try oftb.forwardInPlace(x);
}

pub fn mixBackward(oftb: OFTB, grad: []f32) !void {
    try oftb.backwardInPlace(grad);
}

comptime {
    _ = Tensor;
    _ = OFTB;
}

test "OFTB forward then backward returns input within 1e-5 tolerance" {
    const allocator = std.testing.allocator;
    var prng = std.Random.DefaultPrng.init(42);
    const random = prng.random();

    const dim: usize = 32;
    const total = dim * 2;

    var input = try Tensor.init(allocator, &.{ 1, total });
    defer input.deinit();
    var i: usize = 0;
    while (i < input.data.len) : (i += 1) {
        input.data[i] = (random.float(f32) - 0.5) * 2.0;
    }

    const original = try allocator.dupe(f32, input.data);
    defer allocator.free(original);

    const oftb = OFTB.init(dim);
    try oftb.forwardInPlace(&input);
    try oftb.backwardInPlace(input.data);

    i = 0;
    while (i < input.data.len) : (i += 1) {
        try std.testing.expectApproxEqAbs(original[i], input.data[i], 1e-5);
    }
}

test "Tensor init rejects invalid shapes" {
    const allocator = std.testing.allocator;
    try std.testing.expectError(error.InvalidShape, Tensor.init(allocator, &.{}));
    try std.testing.expectError(error.InvalidShape, Tensor.init(allocator, &.{ 4, 0 }));
}

test "OFTB rejects mismatched tensor size" {
    const allocator = std.testing.allocator;
    var input = try Tensor.init(allocator, &.{ 1, 16 });
    defer input.deinit();
    const oftb = OFTB.init(32);
    try std.testing.expectError(error.DimensionMismatch, oftb.forwardInPlace(&input));
    try std.testing.expectError(error.DimensionMismatch, oftb.backwardInPlace(input.data));
}

test "mixForward and mixBackward round trip" {
    const allocator = std.testing.allocator;
    var prng = std.Random.DefaultPrng.init(7);
    const random = prng.random();

    const dim: usize = 13;
    const total = dim * 2;

    var input = try Tensor.init(allocator, &.{ 1, total });
    defer input.deinit();
    var i: usize = 0;
    while (i < input.data.len) : (i += 1) {
        input.data[i] = (random.float(f32) - 0.5) * 2.0;
    }

    const original = try allocator.dupe(f32, input.data);
    defer allocator.free(original);

    const oftb = OFTB.init(dim);
    try mixForward(oftb, &input);
    try mixBackward(oftb, input.data);

    i = 0;
    while (i < input.data.len) : (i += 1) {
        try std.testing.expectApproxEqAbs(original[i], input.data[i], 1e-5);
    }
}

